INSERT INTO public.email_templates (id, tenant_id, key, name, subject, body, updated_at, created_at) VALUES
	('28c02788-4e95-43f7-8490-efc503946e4f', '78e3bdf6-326e-4356-82af-a6df89f3b6f2', 'invoice_reminder', 'Invoice reminder', 'Reminder: invoice {{ invoice.number }} is overdue', '<p>Hello {{ coalesce(invoice.contact?.firstName, ''there'') }},</p><p>Invoice <b>{{ invoice.number }}</b> for {{ formatMoney(invoice.balanceCents) }} was due on {{ formatDate(invoice.dueDate, ''MMM D, YYYY'') }}.</p><p>You can view and pay it here: <a href="{{ invoice.publicUrl }}">{{ invoice.publicUrl }}</a></p>', '2026-10-05 03:24:11.772+03', '2026-10-05 03:24:11.772+03'),
	('acd7fddc-35b0-4dcb-80d7-36cf4918eddb', '78e3bdf6-326e-4356-82af-a6df89f3b6f2', 'invoice_final_notice', 'Invoice final notice', 'Final notice: invoice {{ invoice.number }}', '<p>Hello {{ coalesce(invoice.contact?.firstName, ''there'') }},</p><p>This is the final notice for invoice <b>{{ invoice.number }}</b> ({{ formatMoney(invoice.balanceCents) }}). Please pay it within 7 days.</p><p><a href="{{ invoice.publicUrl }}">View invoice</a></p>', '2026-10-05 03:24:11.773+03', '2026-10-05 03:24:11.773+03'),
	('596f79e6-af11-4646-8584-8a528321541c', '78e3bdf6-326e-4356-82af-a6df89f3b6f2', 'invoice_thanks', 'Payment received', 'Thank you for your payment ({{ invoice.number }})', '<p>We received your payment for invoice <b>{{ invoice.number }}</b>. Thank you!</p>', '2026-10-05 03:24:11.773+03', '2026-10-05 03:24:11.773+03'),
	('8951b838-b2dd-483f-8e32-2a868892d8f0', '78e3bdf6-326e-4356-82af-a6df89f3b6f2', 'invoice_sent', 'Invoice sent', 'Invoice {{ invoice.number }} from {{ tenant.name }}', '<p>Hello,</p><p>Please find invoice <b>{{ invoice.number }}</b> for {{ formatMoney(invoice.totalCents) }} attached, due {{ formatDate(invoice.dueDate, ''MMM D, YYYY'') }}.</p><p><a href="{{ invoice.publicUrl }}">View online</a></p>', '2026-10-05 03:24:11.773+03', '2026-10-05 03:24:11.773+03'),
	('3fce6149-399f-4184-b074-203409513041', '78e3bdf6-326e-4356-82af-a6df89f3b6f2', 'welcome', 'Welcome', 'Welcome, {{ contact.firstName }}', '<p>Hi {{ contact.firstName }}, thanks for your interest!</p>', '2026-10-05 03:24:11.774+03', '2026-10-05 03:24:11.774+03'),
