	('b54cf95a-af05-45ba-9772-b7683115a159', '21c3e033-6d3e-43e4-bd9a-1c665a4ec2e7', 'invoice_final_notice', 'Invoice final notice', 'Final notice: invoice {{ invoice.number }}', '<p>Hello {{ coalesce(invoice.contact?.firstName, ''there'') }},</p><p>This is the final notice for invoice <b>{{ invoice.number }}</b> ({{ formatMoney(invoice.balanceCents) }}). Please pay it within 7 days.</p><p><a href="{{ invoice.publicUrl }}">View invoice</a></p>', '2026-10-05 03:24:12.772+03', '2026-10-05 03:24:12.772+03'),
	('b0909f5e-3b56-47e6-ac82-e84875d21bf0', '21c3e033-6d3e-43e4-bd9a-1c665a4ec2e7', 'invoice_thanks', 'Payment received', 'Thank you for your payment ({{ invoice.number }})', '<p>We received your payment for invoice <b>{{ invoice.number }}</b>. Thank you!</p>', '2026-10-05 03:24:12.773+03', '2026-10-05 03:24:12.773+03'),
	('3c98d478-892e-44aa-ad92-90d1c134d31e', '21c3e033-6d3e-43e4-bd9a-1c665a4ec2e7', 'invoice_sent', 'Invoice sent', 'Invoice {{ invoice.number }} from {{ tenant.name }}', '<p>Hello,</p><p>Please find invoice <b>{{ invoice.number }}</b> for {{ formatMoney(invoice.totalCents) }} attached, due {{ formatDate(invoice.dueDate, ''MMM D, YYYY'') }}.</p><p><a href="{{ invoice.publicUrl }}">View online</a></p>', '2026-10-05 03:24:12.773+03', '2026-10-05 03:24:12.773+03'),
	('47977579-61b0-4e84-b75d-e0d5467dce9e', '21c3e033-6d3e-43e4-bd9a-1c665a4ec2e7', 'welcome', 'Welcome', 'Welcome, {{ contact.firstName }}', '<p>Hi {{ contact.firstName }}, thanks for your interest!</p>', '2026-10-05 03:24:12.773+03', '2026-10-05 03:24:12.773+03');
