INSERT INTO public.workflow_drafts (tenant_id, workflow_id, definition, updated_by, updated_at) VALUES
	('78e3bdf6-326e-4356-82af-a6df89f3b6f2', 'db1eef25-ae20-4f5e-8ad5-7e88fe896531', '{"name": "Overdue invoice follow-up", "edges": [{"to": "big", "from": "$trigger"}, {"to": "notify", "from": "big", "label": "true"}, {"to": "task", "from": "big", "label": "true"}, {"to": "remind", "from": "big", "label": "false"}, {"to": "remind", "from": "notify"}, {"to": "remind", "from": "task"}, {"to": "wait_paid", "from": "remind"}, {"to": "escalate", "from": "wait_paid", "label": "timeout"}, {"to": "final", "from": "escalate", "label": "approved"}], "nodes": [{"id": "big", "type": "condition", "config": {"expr": "invoice.totalCents > 100000"}}, {"id": "notify", "type": "notify", "config": {"to": "invoice.company.owner", "message": "Invoice {{ invoice.number }} is overdue ({{ formatMoney(invoice.totalCents, invoice.currency) }})"}}, {"id": "task", "type": "create_task", "config": {"dueAt": "now() + days(1)", "title": "Call {{ invoice.company.name }} about {{ invoice.number }}", "assignee": "invoice.company.owner", "relatedTo": "invoice"}}, {"id": "remind", "type": "send_email", "retry": {"backoff": "exponential", "initialMs": 30000, "maxAttempts": 5}, "config": {"to": "invoice.contact?.email", "template": "invoice_reminder", "attachInvoice": true}}, {"id": "wait_paid", "type": "wait_for_event", "config": {"id": "invoice.id", "event": "invoice.paid", "entity": "invoice", "timeout": "days(3)"}}, {"id": "escalate", "type": "approval", "config": {"title": "Send final notice for {{ invoice.number }}?", "timeout": "days(2)", "assignees": "role(''manager'')"}}, {"id": "final", "type": "send_email", "config": {"to": "invoice.contact?.email", "template": "invoice_final_notice"}}], "trigger": {"type": "record_condition", "dedupe": "invoice.id", "entity": "invoice", "condition": "invoice.status in [''sent'', ''partially_paid'', ''overdue''] and invoice.dueDate < now() - days(1)"}}', '22a07212-ab50-4a96-8890-8e91501e10e8', '2026-10-05 03:24:12.675+03'),
	('78e3bdf6-326e-4356-82af-a6df89f3b6f2', '4fbb1d6c-dad4-4540-bc45-8565d80ffe5a', '{"name": "New lead → round-robin owner", "edges": [{"to": "assign", "from": "$trigger"}, {"to": "welcome", "from": "assign"}], "nodes": [{"id": "assign", "type": "update_record", "config": {"fields": {"ownerId": "role(''member'')[run.number % len(role(''member''))]?.id"}, "record": "contact"}}, {"id": "welcome", "type": "create_task", "config": {"dueAt": "now() + days(1)", "title": "Welcome call with {{ contact.name }}", "assignee": "role(''member'')[run.number % len(role(''member''))]", "relatedTo": "contact"}}], "trigger": {"type": "record_event", "event": "contact.created", "entity": "contact", "filter": "contact.status == ''lead'' and contact.ownerId == null"}}', '22a07212-ab50-4a96-8890-8e91501e10e8', '2026-10-05 03:24:12.692+03'),
	('78e3bdf6-326e-4356-82af-a6df89f3b6f2', '297c429e-026c-4d57-a686-88f9a006f6f9', '{"name": "Stale deal nudge", "edges": [{"to": "nudge_owner", "from": "$trigger"}, {"to": "wait_week", "from": "nudge_owner"}, {"to": "nudge_manager", "from": "wait_week"}], "nodes": [{"id": "nudge_owner", "type": "notify", "config": {"to": "deal.owner", "message": "No activity on {{ deal.title }} for 14 days"}}, {"id": "wait_week", "type": "wait_duration", "config": {"duration": "days(7)"}}, {"id": "nudge_manager", "type": "notify", "config": {"to": "role(''manager'')", "message": "{{ deal.title }} ({{ formatMoney(deal.amountCents) }}) is still stale"}}], "trigger": {"type": "record_condition", "dedupe": "deal.id + '':'' + formatDate(deal.lastActivityAt, ''YYYY-MM-DD'')", "entity": "deal", "condition": "deal.closedAt == null and deal.lastActivityAt < now() - days(14)"}}', '22a07212-ab50-4a96-8890-8e91501e10e8', '2026-10-05 03:24:12.698+03'),
	('78e3bdf6-326e-4356-82af-a6df89f3b6f2', '824881b6-db00-4ee6-89da-d93f4e24637e', '{"name": "Deal won → onboarding", "edges": [{"to": "has_company", "from": "$trigger"}, {"to": "kickoff", "from": "has_company", "label": "true"}, {"to": "welcome_pack", "from": "has_company", "label": "true"}, {"to": "invoice", "from": "has_company", "label": "true"}, {"to": "note", "from": "kickoff"}, {"to": "note", "from": "welcome_pack"}, {"to": "note", "from": "invoice"}], "nodes": [{"id": "has_company", "type": "condition", "config": {"expr": "deal.company != null"}}, {"id": "kickoff", "type": "create_task", "config": {"dueAt": "now() + days(2)", "title": "Kickoff call: {{ deal.title }}", "assignee": "deal.owner", "relatedTo": "deal"}}, {"id": "welcome_pack", "type": "create_task", "config": {"dueAt": "now() + days(3)", "title": "Send welcome pack to {{ deal.company?.name }}", "assignee": "deal.owner", "relatedTo": "deal"}}, {"id": "invoice", "type": "create_invoice", "config": {"deal": "deal", "dueIn": "days(14)", "amount": "deal.amountCents", "company": "deal.company", "contact": "deal.contact", "description": "{{ deal.title }}"}}, {"id": "note", "type": "add_note", "config": {"body": "Onboarding started: 2 tasks and a draft invoice were created.", "subject": "deal"}}], "trigger": {"type": "record_event", "event": "deal.won", "entity": "deal"}}', '22a07212-ab50-4a96-8890-8e91501e10e8', '2026-10-05 03:24:12.703+03'),
	('78e3bdf6-326e-4356-82af-a6df89f3b6f2', '6f08145c-3158-4f01-b813-c31bc2d50ac0', '{"name": "Invoice paid → thank you + Slack", "edges": [{"to": "thanks", "from": "$trigger"}, {"to": "slack", "from": "thanks"}], "nodes": [{"id": "thanks", "type": "send_email", "config": {"to": "invoice.contact?.email", "template": "invoice_thanks"}}, {"id": "slack", "type": "http_request", "config": {"url": "{{ secret(''slack_webhook_url'') }}", "body": "{\"text\": \"Invoice {{ invoice.number }} from {{ invoice.company.name }} paid: {{ formatMoney(invoice.totalCents) }}\"}", "method": "POST", "headers": {"content-type": "application/json"}}}], "trigger": {"type": "record_event", "event": "invoice.paid", "entity": "invoice"}}', '22a07212-ab50-4a96-8890-8e91501e10e8', '2026-10-05 03:24:12.707+03'),
	('78e3bdf6-326e-4356-82af-a6df89f3b6f2', '05077d96-b934-424d-b9ed-de776272a2cf', '{"name": "Weekly pipeline digest", "edges": [{"to": "report", "from": "$trigger"}, {"to": "digest", "from": "report"}], "nodes": [{"id": "report", "type": "http_request", "config": {"url": "{{ secret(''api_base_url'') }}/v1/reports/pipeline", "method": "GET", "headers": {"authorization": "Bearer {{ secret(''reports_api_token'') }}"}}}, {"id": "digest", "type": "send_email", "config": {"to": "role(''manager'')", "body": "Open pipeline: {{ formatMoney(steps.report.output.body.summary.openCents, ''USD'') }} in {{ steps.report.output.body.summary.openDeals }} deals. Won this week: {{ formatMoney(steps.report.output.body.summary.wonLast7DaysCents, ''USD'') }}.", "subject": "Weekly pipeline digest"}}], "trigger": {"cron": "0 9 * * 1", "type": "schedule"}}', '22a07212-ab50-4a96-8890-8e91501e10e8', '2026-10-05 03:24:12.711+03');
INSERT INTO public.workflows (id, tenant_id, name, description, status, active_version, trigger_type, trigger_key, webhook_secret, template_key, created_by, created_at, updated_at, next_fire_at, last_scan_at, run_counter) VALUES
	('db1eef25-ae20-4f5e-8ad5-7e88fe896531', '78e3bdf6-326e-4356-82af-a6df89f3b6f2', 'Overdue invoice follow-up', 'When an invoice is overdue: notify the owner and create a task for big invoices, send a reminder, wait for payment, ask a manager before the final notice.', 'active', 1, 'record_condition', 'invoice', 'jOxw9YLi1i7DbYzYPsbqTDuT', 'overdue_invoice', '22a07212-ab50-4a96-8890-8e91501e10e8', '2026-10-05 03:24:12.674+03', '2026-10-05 03:24:12.69+03', NULL, NULL, 0),
	('4fbb1d6c-dad4-4540-bc45-8565d80ffe5a', '78e3bdf6-326e-4356-82af-a6df89f3b6f2', 'New lead → round-robin owner', 'Assign new leads to team members in turn and create a welcome task.', 'active', 1, 'record_event', 'contact.created', 'GC06AQq1StE53I28TtL2Lp5t', 'new_lead_round_robin', '22a07212-ab50-4a96-8890-8e91501e10e8', '2026-10-05 03:24:12.692+03', '2026-10-05 03:24:12.697+03', NULL, NULL, 0),
	('297c429e-026c-4d57-a686-88f9a006f6f9', '78e3bdf6-326e-4356-82af-a6df89f3b6f2', 'Stale deal nudge', 'A deal without activity for 14 days: notify the owner, and a manager 7 days later.', 'active', 1, 'record_condition', 'deal', '3MdYiMNDn4dqOcuzW9ZPRi5y', 'stale_deal_nudge', '22a07212-ab50-4a96-8890-8e91501e10e8', '2026-10-05 03:24:12.698+03', '2026-10-05 03:24:12.701+03', NULL, NULL, 0),
	('824881b6-db00-4ee6-89da-d93f4e24637e', '78e3bdf6-326e-4356-82af-a6df89f3b6f2', 'Deal won → onboarding', 'Create onboarding tasks and a draft invoice when a deal is won.', 'active', 1, 'record_event', 'deal.won', 'n-ieCBCYG1lkTMEvj_7gj1tX', 'deal_won', '22a07212-ab50-4a96-8890-8e91501e10e8', '2026-10-05 03:24:12.702+03', '2026-10-05 03:24:12.706+03', NULL, NULL, 0),
	('6f08145c-3158-4f01-b813-c31bc2d50ac0', '78e3bdf6-326e-4356-82af-a6df89f3b6f2', 'Invoice paid → thank you + Slack', 'Send a thank-you email and post to Slack when an invoice is paid.', 'active', 1, 'record_event', 'invoice.paid', 'mte5c7JHec7hpAGRfdutR-eM', 'invoice_paid_thanks', '22a07212-ab50-4a96-8890-8e91501e10e8', '2026-10-05 03:24:12.707+03', '2026-10-05 03:24:12.71+03', NULL, NULL, 0),
	('05077d96-b934-424d-b9ed-de776272a2cf', '78e3bdf6-326e-4356-82af-a6df89f3b6f2', 'Weekly pipeline digest', 'Every Monday at 09:00 (tenant time zone) email managers a pipeline summary.', 'active', 1, 'schedule', '0 9 * * 1', '9q7RxDR4j8mQf2N_uLYA6oa_', 'weekly_pipeline_digest', '22a07212-ab50-4a96-8890-8e91501e10e8', '2026-10-05 03:24:12.711+03', '2026-10-05 03:24:12.731+03', '2026-10-05 10:00:00+03', NULL, 0);
INSERT INTO public.workflow_versions (tenant_id, workflow_id, version, definition, checksum, published_by, published_at) VALUES
	('78e3bdf6-326e-4356-82af-a6df89f3b6f2', 'db1eef25-ae20-4f5e-8ad5-7e88fe896531', 1, '{"name": "Overdue invoice follow-up", "edges": [{"to": "big", "from": "$trigger"}, {"to": "notify", "from": "big", "label": "true"}, {"to": "task", "from": "big", "label": "true"}, {"to": "remind", "from": "big", "label": "false"}, {"to": "remind", "from": "notify"}, {"to": "remind", "from": "task"}, {"to": "wait_paid", "from": "remind"}, {"to": "escalate", "from": "wait_paid", "label": "timeout"}, {"to": "final", "from": "escalate", "label": "approved"}], "nodes": [{"id": "big", "type": "condition", "config": {"expr": "invoice.totalCents > 100000"}}, {"id": "notify", "type": "notify", "config": {"to": "invoice.company.owner", "message": "Invoice {{ invoice.number }} is overdue ({{ formatMoney(invoice.totalCents, invoice.currency) }})"}}, {"id": "task", "type": "create_task", "config": {"dueAt": "now() + days(1)", "title": "Call {{ invoice.company.name }} about {{ invoice.number }}", "assignee": "invoice.company.owner", "relatedTo": "invoice"}}, {"id": "remind", "type": "send_email", "retry": {"backoff": "exponential", "initialMs": 30000, "maxAttempts": 5}, "config": {"to": "invoice.contact?.email", "template": "invoice_reminder", "attachInvoice": true}}, {"id": "wait_paid", "type": "wait_for_event", "config": {"id": "invoice.id", "event": "invoice.paid", "entity": "invoice", "timeout": "days(3)"}}, {"id": "escalate", "type": "approval", "config": {"title": "Send final notice for {{ invoice.number }}?", "timeout": "days(2)", "assignees": "role(''manager'')"}}, {"id": "final", "type": "send_email", "config": {"to": "invoice.contact?.email", "template": "invoice_final_notice"}}], "trigger": {"type": "record_condition", "dedupe": "invoice.id", "entity": "invoice", "condition": "invoice.status in [''sent'', ''partially_paid'', ''overdue''] and invoice.dueDate < now() - days(1)"}}', '80f33cca3c3ab9b68b02a07697b6da94d156084d3c95e98977d108f7289e24d3', '22a07212-ab50-4a96-8890-8e91501e10e8', '2026-10-05 03:24:12.689+03'),
	('78e3bdf6-326e-4356-82af-a6df89f3b6f2', '4fbb1d6c-dad4-4540-bc45-8565d80ffe5a', 1, '{"name": "New lead → round-robin owner", "edges": [{"to": "assign", "from": "$trigger"}, {"to": "welcome", "from": "assign"}], "nodes": [{"id": "assign", "type": "update_record", "config": {"fields": {"ownerId": "role(''member'')[run.number % len(role(''member''))]?.id"}, "record": "contact"}}, {"id": "welcome", "type": "create_task", "config": {"dueAt": "now() + days(1)", "title": "Welcome call with {{ contact.name }}", "assignee": "role(''member'')[run.number % len(role(''member''))]", "relatedTo": "contact"}}], "trigger": {"type": "record_event", "event": "contact.created", "entity": "contact", "filter": "contact.status == ''lead'' and contact.ownerId == null"}}', 'e42b04e805e11995f321974cac84a517fed31989fc136ac91be7df524116ea5d', '22a07212-ab50-4a96-8890-8e91501e10e8', '2026-10-05 03:24:12.696+03'),
	('78e3bdf6-326e-4356-82af-a6df89f3b6f2', '297c429e-026c-4d57-a686-88f9a006f6f9', 1, '{"name": "Stale deal nudge", "edges": [{"to": "nudge_owner", "from": "$trigger"}, {"to": "wait_week", "from": "nudge_owner"}, {"to": "nudge_manager", "from": "wait_week"}], "nodes": [{"id": "nudge_owner", "type": "notify", "config": {"to": "deal.owner", "message": "No activity on {{ deal.title }} for 14 days"}}, {"id": "wait_week", "type": "wait_duration", "config": {"duration": "days(7)"}}, {"id": "nudge_manager", "type": "notify", "config": {"to": "role(''manager'')", "message": "{{ deal.title }} ({{ formatMoney(deal.amountCents) }}) is still stale"}}], "trigger": {"type": "record_condition", "dedupe": "deal.id + '':'' + formatDate(deal.lastActivityAt, ''YYYY-MM-DD'')", "entity": "deal", "condition": "deal.closedAt == null and deal.lastActivityAt < now() - days(14)"}}', 'f4dccd09a915e00c85a0ae453a3bd12ec4e268e1ea4bda0da3f7d48a6479f496', '22a07212-ab50-4a96-8890-8e91501e10e8', '2026-10-05 03:24:12.701+03'),
	('78e3bdf6-326e-4356-82af-a6df89f3b6f2', '824881b6-db00-4ee6-89da-d93f4e24637e', 1, '{"name": "Deal won → onboarding", "edges": [{"to": "has_company", "from": "$trigger"}, {"to": "kickoff", "from": "has_company", "label": "true"}, {"to": "welcome_pack", "from": "has_company", "label": "true"}, {"to": "invoice", "from": "has_company", "label": "true"}, {"to": "note", "from": "kickoff"}, {"to": "note", "from": "welcome_pack"}, {"to": "note", "from": "invoice"}], "nodes": [{"id": "has_company", "type": "condition", "config": {"expr": "deal.company != null"}}, {"id": "kickoff", "type": "create_task", "config": {"dueAt": "now() + days(2)", "title": "Kickoff call: {{ deal.title }}", "assignee": "deal.owner", "relatedTo": "deal"}}, {"id": "welcome_pack", "type": "create_task", "config": {"dueAt": "now() + days(3)", "title": "Send welcome pack to {{ deal.company?.name }}", "assignee": "deal.owner", "relatedTo": "deal"}}, {"id": "invoice", "type": "create_invoice", "config": {"deal": "deal", "dueIn": "days(14)", "amount": "deal.amountCents", "company": "deal.company", "contact": "deal.contact", "description": "{{ deal.title }}"}}, {"id": "note", "type": "add_note", "config": {"body": "Onboarding started: 2 tasks and a draft invoice were created.", "subject": "deal"}}], "trigger": {"type": "record_event", "event": "deal.won", "entity": "deal"}}', '2c4f78e06660cb72e4e1640d3356a5f9c2128ad20bc2ba4859bdba557751b55c', '22a07212-ab50-4a96-8890-8e91501e10e8', '2026-10-05 03:24:12.705+03'),
	('78e3bdf6-326e-4356-82af-a6df89f3b6f2', '6f08145c-3158-4f01-b813-c31bc2d50ac0', 1, '{"name": "Invoice paid → thank you + Slack", "edges": [{"to": "thanks", "from": "$trigger"}, {"to": "slack", "from": "thanks"}], "nodes": [{"id": "thanks", "type": "send_email", "config": {"to": "invoice.contact?.email", "template": "invoice_thanks"}}, {"id": "slack", "type": "http_request", "config": {"url": "{{ secret(''slack_webhook_url'') }}", "body": "{\"text\": \"Invoice {{ invoice.number }} from {{ invoice.company.name }} paid: {{ formatMoney(invoice.totalCents) }}\"}", "method": "POST", "headers": {"content-type": "application/json"}}}], "trigger": {"type": "record_event", "event": "invoice.paid", "entity": "invoice"}}', 'fd9a2c447114ab99e9e20cffe8badf6fef268aa18e223cb46993d6c3c96b227e', '22a07212-ab50-4a96-8890-8e91501e10e8', '2026-10-05 03:24:12.709+03'),
	('78e3bdf6-326e-4356-82af-a6df89f3b6f2', '05077d96-b934-424d-b9ed-de776272a2cf', 1, '{"name": "Weekly pipeline digest", "edges": [{"to": "report", "from": "$trigger"}, {"to": "digest", "from": "report"}], "nodes": [{"id": "report", "type": "http_request", "config": {"url": "{{ secret(''api_base_url'') }}/v1/reports/pipeline", "method": "GET", "headers": {"authorization": "Bearer {{ secret(''reports_api_token'') }}"}}}, {"id": "digest", "type": "send_email", "config": {"to": "role(''manager'')", "body": "Open pipeline: {{ formatMoney(steps.report.output.body.summary.openCents, ''USD'') }} in {{ steps.report.output.body.summary.openDeals }} deals. Won this week: {{ formatMoney(steps.report.output.body.summary.wonLast7DaysCents, ''USD'') }}.", "subject": "Weekly pipeline digest"}}], "trigger": {"cron": "0 9 * * 1", "type": "schedule"}}', 'e52bae8b36db1fac0117268febada3edc91618af6536b0f4268696a1e3cf6b24', '22a07212-ab50-4a96-8890-8e91501e10e8', '2026-10-05 03:24:12.729+03');
